class Unionfind:
    def __init__(self, n):
        self.parents = [-1] * n
        self.dist = [0] * n

    def find(self, x):
        if self.parents[x] < 0:
            return x, self.dist[x]
        else:
            tmp = self.find(self.parents[x])
            self.parents[x] = tmp[0]
            self.dist[x] += tmp[1]
            return self.parents[x], self.dist[x]

    def union(self, x, y, d):
        rx = self.find(x)[0]
        ry = self.find(y)[0]
        diff = self.dist[y] - self.dist[x] - d
        if rx == ry:
            if diff != 0:
                return True
            return False
        if diff < 0:
            rx, ry = ry, rx
            diff = -diff
        self.parents[ry] = min(self.parents[ry], self.parents[rx] - diff)
        self.parents[rx] = ry
        self.dist[rx] = diff
        return False


