import sys

sys.setrecursionlimit(10**9)
read = sys.stdin.read


class Unionfind:
    def __init__(self, n):
        self.parents = [-1] * n
        self.dist = [0] * n

    def find(self, x):
        if self.parents[x] < 0:
            return self.dist[x], x
        else:
            tmp = self.find(self.parents[x])
            self.dist[x] += tmp[0]
            self.parents[x] = tmp[1]
        return self.dist[x], self.parents[x]

    def union(self, x, y, d):
        _, rx = self.find(x)
        _, ry = self.find(y)
        diff = self.dist[y] - self.dist[x] - d
        if rx == ry:
            if diff != 0:
                return True
            return False
        if diff < 0:
            rx, ry = ry, rx
            diff = -diff
        self.parents[ry] = min(self.parents[ry], self.parents[rx] - diff)
        self.parents[rx] = ry
        self.dist[rx] = diff
        return False


def main():
