class Solution(object):
    def maxValue(self, n, index, maxSum):
        def calculate_sum(num, index, n):
            if (num - index) > 0:
                sx = num * index + index // 2 - (index * index) // 2
            else:
                sx = num * (num + 1) // 2 + abs(index - num)
            if (num - (n - index) - 1) > 0:
                dx = (
                    num * (num + 1) // 2
                    - (num - (n - index) - 1) * (num - (n - index)) // 2
                )
            else:
                dx = num * (num + 1) // 2 + abs(n - (index + num) + 1)
            return dx + sx - num

        check = calculate_sum(int(math.sqrt(maxSum)), index + 1, n)
        if check > maxSum:
            left, right = 1, int(math.sqrt(maxSum))
        else:
            left, right = int(math.sqrt(maxSum)), maxSum
        while left < right:
            mid = (left + right + 1) // 2
            if calculate_sum(mid, index + 1, n) <= maxSum:
                left = mid
            else:
                right = mid - 1
        return left

