class Solution(object):
    def reverseOddLevels(self, root):
        q = deque([root.left, root.right])
        tmp = deque()
        dq = deque()
        level = 1
        while q or tmp:
            if level % 2 != 0:
                tmp = deque()
                if q[0] is None:
                    return root
                while q:
                    l, r = q.popleft(), q.pop()
                    temp = l.val
                    l.val = r.val
                    r.val = temp
                    dq.append(r)
                    tmp.append(l.left)
