    def shortestPathAllKeys(self, grid):
        m = len(grid)
        n = len(grid[0])
        arr = deque([])
        numOfKeys = 0
        keys = {"a": 0, "b": 1, "c": 2, "d": 3, "e": 4, "f": 5}
