                if n in primes:
                    total = total + p0
                    total = total + p0 * path0
                else:
                    total = total + p1
                    total = total + p1 * path0 + p0 * path1
                path0, path1 = path0 + p0, path1 + p1
            self.ans = self.ans + total
            if n in primes:
                return (0, path0 + 1)
            else:
