class Solution(object):
    def minEatingSpeed(self, piles, h):
        if h == len(piles):
            return max(piles)
        s = sum(piles)
        mini = s / h + 1 if s % h > 0 else s / h
        maxi = s / (h - len(piles) + 1) + 1
        return self.binary_search(mini, maxi, h, piles)

    def binary_search(self, mini, maxi, h, piles):
