class Solution(object):
    def countPaths(self, n, edges):
        self.ans = 0
        primes = self.getprime(n)
        children = defaultdict(set)
        for a, b in edges:
            children[a].add(b)
            children[b].add(a)
        self.dfs(1, children, set(), primes)
        return self.ans

    def dfs(self, n, children, already, primes):
        realchild = children[n] - already
        already.add(n)
        if len(realchild) == 0:
            if n in primes:
                return (0, 1)
            else:
                return (1, 0)
        else:
            total = 0
            path0 = 0
            path1 = 0
            for r in realchild:
                p0, p1 = self.dfs(r, children, already, primes)
                if n in primes:
                    total = total + p0
                    total = total + p0 * path0
                else:
                    total = total + p1
                    total = total + p1 * path0 + p0 * path1
                path0, path1 = path0 + p0, path1 + p1
            self.ans = self.ans + total
            if n in primes:
                return (0, path0 + 1)
            else:
                return (path0 + 1, path1)

    def getprime(self, n):
        ans = set()
        record = [0] * (n + 1)
        for i in range(2, len(record)):
            if record[i] == 0:
                ans.add(i)
                start = i + i
                while start <= n:
                    record[start] = 1
                    start = start + i
        return ans

