    def treeQueries(self, root, queries):
        dp = defaultdict(int)
        stack = [(root, 0)]
        maxHeight = 0
        while stack:
            currNode, currHeight = stack.pop()
            dp[currNode.val] = maxHeight
            maxHeight = max(maxHeight, currHeight)
            if currNode.right:
                stack.append((currNode.right, currHeight + 1))
            if currNode.left:
                stack.append((currNode.left, currHeight + 1))
        dpReverse = defaultdict(int)
        stack = [(root, 0)]
        maxHeight = 0
        while stack:
            currNode, currHeight = stack.pop()
            dpReverse[currNode.val] = maxHeight
            maxHeight = max(maxHeight, currHeight)
            if currNode.left:
                stack.append((currNode.left, currHeight + 1))
            if currNode.right:
                stack.append((currNode.right, currHeight + 1))
        answer = [0] * len(queries)
        for idx, query in enumerate(queries):
            answer[idx] = max(dp[query], dpReverse[query])
        return answer

