    def bstFromPreorder(self, preorder: List[int]) -> Optional[TreeNode]:
        def create_tree(preorder):
            if preorder is None:
                return None
            current_root_val = preorder[0]
            curr_root = TreeNode(current_root_val)
            left_sub_list = [x for x in preorder if x < current_root_val]
