        DiagRight = copy.deepcopy(grid)
        DiagLeft = copy.deepcopy(grid)
        for i in range(m):
            for j in range(n):
                if j > 0:
                    rowPrefix[i][j] += rowPrefix[i][j - 1]
                if i > 0:
                    colPrefix[i][j] += colPrefix[i - 1][j]
                if i > 0 and j > 0:
                    DiagRight[i][j] += DiagRight[i - 1][j - 1]
                if i > 0 and j + 1 < n:
                    DiagLeft[i][j] += DiagLeft[i - 1][j + 1]
        maxSquare = min(m, n)
        for size in range(maxSquare, 1, -1):
            for row in range(m - size + 1):
                for col in range(n - size + 1):
