                    maxc = size + col - 1
                    DR = DiagRight[maxr][maxc] - (
                        DiagRight[row - 1][col - 1] if row > 0 and col > 0 else 0
                    )
                    DL = DiagLeft[maxr][col] - (
                        DiagLeft[row - 1][col + size]
                        if row > 0 and col + size < n
                        else 0
                    )
